export interface ChartAxis {
    categories?: string[];
    /** Configure a crosshair that follows either the mouse pointer or the hovered point. */
    crosshair?: AxisCrosshair;
    timestamps?: number[];
    type?: ChartAxisType;
    /** The axis labels show the number or category for each tick. */
    labels?: ChartAxisLabels;
    /** The color of the line marking the axis itself. */
    lineColor?: string;
    /**
     * Whether to display the line marking the axis itself.
     * @default true
     */
    lineVisible?: boolean;
    title?: ChartAxisTitle;
    /**
     * The minimum value of the axis. If undefined the min value is automatically calculated.
     *
     * The value type depends on the axis scale:
     * - For `linear` and `logarithmic` axes: numeric value
     * - For `datetime` axes: timestamp (milliseconds since Unix epoch)
     * - For `category` axes: index of the element in the categories array (which has been processed according to the specified `order` property)
     *
     * Note: min/max is not supported for category axes in waterfall and heatmap visualizations.
     */
    min?: number;
    /**
     * The maximum value of the axis. If undefined the max value is automatically calculated.
     *
     * The value type depends on the axis scale:
     * - For `linear` and `logarithmic` axes: numeric value
     * - For `datetime` axes: timestamp (milliseconds since Unix epoch)
     * - For `category` axes: index of the element in the categories array (which has been processed according to the specified `order` property)
     *
     * Note: min/max is not supported for category axes in waterfall and heatmap visualizations.
     */
    max?: number;
    /**
     * The grid lines settings.
     * Unavailable for some visualizations, such as a heatmap.
     */
    grid?: {
        /**
         * Enable or disable the grid lines.
         * @default true
         */
        enabled?: boolean;
    };
    ticks?: ChartAxisTicks;
    /**
     * Legacy maximum-side padding. On linear and datetime axes, a fraction of the value range before padding.
     * Ignored on axes normalized with `stacking: 'percent'` and on X when the range slider is enabled.
     * Datetime Y axes with explicit `timestamps` also ignore it.
     * @default 0.05 for Y axis, 0.01 for X axis
     * @deprecated On linear and datetime axes where this option adds space, use `padding.max`
     * with a percentage string: `maxPadding: 0.25` becomes `padding: {max: '25%'}`.
     * Numbers in `padding` are pixels. Unlike `maxPadding`, `padding` does not extend zoomed boundaries.
     * On logarithmic axes, migrate to percentages of the logarithmic range; the legacy
